lemma bracketFam_apply_eq_zero_of_map_lie {φ : Module.Dual ℝ G.lieSubalgebra}
    (hφ : ∀ x y : G.lieSubalgebra, φ ⁅x, y⁆ = 0) (f g : Module.Dual ℝ G.lieSubalgebra →ₗ[ℝ] B) :
    bracketFam f g φ = 0

lemma bracketFam_swap_of_commute {f g : Module.Dual ℝ G.lieSubalgebra →ₗ[ℝ] B}
    (hfg : ∀ φ ψ, Commute (f φ) (g ψ)) :
    bracketFam g f = - bracketFam f g

lemma bracketFam_apply_mem_submodule {M : Submodule ℂ B}
    {f g : Module.Dual ℝ G.lieSubalgebra →ₗ[ℝ] B}
    (hfg : ∀ ψ χ, f ψ * g χ ∈ M) (φ : Module.Dual ℝ G.lieSubalgebra) :
    bracketFam f g φ ∈ M

lemma mul_mem_massWeightEigenspace {P : B →ₐ[ℂ] Polynomial B} {w w' : ℕ} {b b' : B}
    (hb : b ∈ massWeightEigenspace P w) (hb' : b' ∈ massWeightEigenspace P w') :
    b * b' ∈ massWeightEigenspace P (w + w')

def TransformsAsGaugeField (repGauge : Representation ℂ G.gaugeJetGroup B)
    (A : Multiset (Fin 1 ⊕ Fin 3) → (Fin 1 ⊕ Fin 3) → Module.Dual ℝ G.lieSubalgebra →ₗ[ℝ] B) :
    Prop

def LorentzTransformsAsGaugeField (repLorentz : Representation ℂ SL(2,ℂ) B)
    (A : Multiset (Fin 1 ⊕ Fin 3) → (Fin 1 ⊕ Fin 3) → Module.Dual ℝ G.lieSubalgebra →ₗ[ℝ] B) :
    Prop

lemma exists_le_of_mem_adjoin_symbols_union (S : Set B) {x : B}
    (hx : x ∈ Algebra.adjoin ℂ (symbols A ∪ S)) :
    ∃ n : ℕ, x ∈ Algebra.adjoin ℂ (symbolsLE A n ∪ S)

lemma algHom_ext {B : Type} [Semiring B] [Algebra ℝ B] {f g : LocalGaugeFieldAlgebra G →ₐ[ℝ] B}
    (h : ∀ (s : Multiset (Fin 1 ⊕ Fin 3)) (μ : Fin 1 ⊕ Fin 3) (φ : Module.Dual ℝ G.lieSubalgebra),
      f (derivA G s μ φ) = g (derivA G s μ φ)) : f = g

lemma adjointDualCoeff_zero_of_evalGaugeJet_eq_one {U : G.gaugeJetGroup}
    (hU : G.evalGaugeJet U = 1) :
    G.adjointDualCoeff U 0 = LinearMap.id

lemma mem_ofSubmonoid_iff {S : Submonoid (Matrix κ κ ℂ)} {hS : IsClosed (S : Set (Matrix κ κ ℂ))}
    {g : GeneralLinearGroup κ ℂ} :
    g ∈ (ofSubmonoid S hS).group ↔ (g : Matrix κ κ ℂ) ∈ S ∧ (↑g⁻¹ : Matrix κ κ ℂ) ∈ S

lemma mem_jetLieAlgebra_of {P : Matrix κ κ SpaceTimeAlgebra → Prop}
    (h0 : ∀ A, P A → (constantCoeff : SpaceTimeAlgebra →+* ℂ).mapMatrix A ∈ G.lieAlgebra)
    (hd : ∀ A, P A → ∀ μ, P (A.map (pderiv μ))) {A : Matrix κ κ SpaceTimeAlgebra}
    (hA : P A) : A ∈ G.jetLieAlgebra

lemma map_coeff_commutator_mem_lieAlgebra {R W : Matrix κ κ SpaceTimeAlgebra}
    (hR : R ∈ G.jetLieAlgebra) (hR0 : (constantCoeff : SpaceTimeAlgebra →+* ℂ).mapMatrix R = 0)
    {p : (Fin 1 ⊕ Fin 3) →₀ ℕ}
    (hW : ∀ q, Finsupp.degree q < Finsupp.degree p → W.map (coeff q) ∈ G.lieAlgebra) :
    (R * W - W * R).map (coeff p) ∈ G.lieAlgebra

lemma eq_oneParameterSubgroup {X : G.lieAlgebra} {t : ℝ} {g : G.group}
    (hg : ((g : GeneralLinearGroup κ ℂ) : Matrix κ κ ℂ) = exp (t • (X : Matrix κ κ ℂ))) :
    g = G.oneParameterSubgroup X t

lemma fromBlocks_mem_lieAlgebra_prod {X₁ : Matrix κ₁ κ₁ ℂ} {X₂ : Matrix κ₂ κ₂ ℂ}
    (hX₁ : X₁ ∈ G₁.lieAlgebra) (hX₂ : X₂ ∈ G₂.lieAlgebra) :
    fromBlocks X₁ 0 0 X₂ ∈ (G₁.prod G₂).lieAlgebra

lemma toBlocks_mem_lieAlgebra_of_mem_lieAlgebra_prod {X : Matrix (κ₁ ⊕ κ₂) (κ₁ ⊕ κ₂) ℂ}
    (hX : X ∈ (G₁.prod G₂).lieAlgebra) :
    X.toBlocks₁₁ ∈ G₁.lieAlgebra ∧ X.toBlocks₂₂ ∈ G₂.lieAlgebra

lemma exp_smul_eq_fromBlocks_of_mem_lieAlgebra_prod {X : Matrix (κ₁ ⊕ κ₂) (κ₁ ⊕ κ₂) ℂ}
    (hX : X ∈ (G₁.prod G₂).lieAlgebra) (t : ℝ) :
    exp (t • X) = fromBlocks (exp (t • X.toBlocks₁₁)) 0 0 (exp (t • X.toBlocks₂₂))

lemma dual_centreGenerator_eq_smul_id {hN : N ≠ 0} {ρ : Representation ℂ (SU N) V} {ε : ℂ}
    (hε : ε ≠ 0) (hρ : ρ (centreGenerator N hN) = ε • LinearMap.id) :
    ρ.dual (centreGenerator N hN) = ε⁻¹ • LinearMap.id

lemma reducesInvariantsTo_bot_span_fund (hN : 3 ≤ N) {T : (Fin 2 → Fin N) → B}
    (hT : (suTensor N).IsEquivariant (fun _ => .fund) ρ (liftComponents T)) :
    ReducesInvariantsTo (fun g : SU N => ρ g) (Submodule.span ℂ (Set.range T)) ⊥

lemma reducesInvariantsTo_bot_span_antiFund (hN : 3 ≤ N) {T : (Fin 2 → Fin N) → B}
    (hT : (suTensor N).IsEquivariant (fun _ => .antiFund) ρ (liftComponents T)) :
    ReducesInvariantsTo (fun g : SU N => ρ g) (Submodule.span ℂ (Set.range T)) ⊥

lemma reducesInvariantsTo_bot_of_isEquivariant_adj {f : SuT[N, .adj] →ₗ[ℂ] B}
    (hf : (suTensor N).IsEquivariant ![.adj] ρ f) :
    ReducesInvariantsTo (fun g : SU N => ρ g) (LinearMap.range f) ⊥

lemma reducesInvariantsTo_bot_span_adj {T : GellMann.Index N → B}
    (hT : (suTensor N).IsEquivariant ![.adj] ρ (liftComponents (T ∘ adjIdx))) :
    ReducesInvariantsTo (fun g : SU N => ρ g) (Submodule.span ℂ (Set.range T)) ⊥

