noncomputable def invariantReductionToEpsilonFund {ρ : Representation ℂ (SU 2) B}
    {T : (Fin 2 → Fin 2) → B}
    (hT : (suTensor 2).IsEquivariant (fun _ => .fund) ρ (liftComponents T)) :
    InvariantReductionToSpan (fun g : SU 2 => ρ g) (Submodule.span ℂ (Set.range T))

noncomputable def invariantReductionToEpsilonAntiFund {ρ : Representation ℂ (SU 2) B}
    {T : (Fin 2 → Fin 2) → B}
    (hT : (suTensor 2).IsEquivariant (fun _ => .antiFund) ρ (liftComponents T)) :
    InvariantReductionToSpan (fun g : SU 2 => ρ g) (Submodule.span ℂ (Set.range T))

lemma invariants_fund_pow_four_eq_span_epsilonPairs :
    ((suTensor 2).tensorRep fun _ : Fin 4 => .fund).invariants
      = Submodule.span ℂ {epsilonPair₁₂, epsilonPair₁₃}

lemma adjointDualCoeff_eq_zero_of_mem_truncationKer {n : ℕ} {U : G.gaugeJetGroup}
    (hU : U ∈ G.truncationKer n) {x : Multiset (Fin 1 ⊕ Fin 3)} (hx : x ≠ 0)
    (hxn : x.card ≤ n) : G.adjointDualCoeff U x = 0

lemma adjointCoeff_mul_of_mem_truncationKer_right (g : G.gaugeJetGroup) {n : ℕ}
    {U : G.gaugeJetGroup}
    (hU : U ∈ G.truncationKer n) {x : Multiset (Fin 1 ⊕ Fin 3)} (hxn : x.card ≤ n) :
    G.adjointCoeff (g * U) x = G.adjointCoeff g x

lemma adjointCoeff_conj_of_mem_truncationKer (g : G.gaugeJetGroup) {n : ℕ} {U : G.gaugeJetGroup}
    (hU : U ∈ G.truncationKer n) {x : Multiset (Fin 1 ⊕ Fin 3)} (hxn : x.card ≤ n) :
    G.adjointCoeff (g * U * g⁻¹) x = G.adjointCoeff 1 x

lemma evalLie_iteratedDerivJ_adjoint_conj_of_mem_truncationKer (g : G.gaugeJetGroup) {n : ℕ}
    {U : G.gaugeJetGroup}
    (hU : U ∈ G.truncationKer n) {s : Multiset (Fin 1 ⊕ Fin 3)} (hs : s.card ≤ n)
    (Y : G.jetLieSubalgebra) : G.evalLie
      (G.iteratedDerivJ s (G.adjointJ (g * U * g⁻¹) Y)) =
      G.evalLie (G.iteratedDerivJ s Y)

lemma symmetrizedMaurerCartanCoeff_eq_zero_of_mem_truncationKer {U : G.truncationKer 0}
    {n : ℕ} (hU : U.1 ∈ G.truncationKer n) {r : Multiset (Fin 1 ⊕ Fin 3)} (hr : r ≠ 0)
    (hrn : r.card ≤ n) : G.symmetrizedMaurerCartanCoeff U ⟨r, hr⟩ = 0

lemma coeff_maurerCartan_eq_zero_of_mem_truncationKer {n : ℕ} {U : G.gaugeJetGroup}
    (hU : U ∈ G.truncationKer n) (ρ : Fin 1 ⊕ Fin 3) {m : (Fin 1 ⊕ Fin 3) →₀ ℕ}
    (hm : Finsupp.degree m < n) (i j : κ) :
    coeff m ((G.maurerCartan U ρ : Matrix κ κ SpaceTimeAlgebra) i j) = 0

lemma span_le_centreEigenspace_of_charge {ρ : Representation ℂ (unitary ℂ) V} {ι : Type*}
    {T : ι → V} {q : ℤ} (hT : ∀ (u : unitary ℂ) (l : ι), ρ u (T l) = ((u : ℂ) ^ q) • T l)
    (z : unitary ℂ) : Submodule.span ℂ (Set.range T) ≤ centreEigenspace ρ z ((z : ℂ) ^ q)

lemma mul_le_centreEigenspace {A : Type} [Ring A] [Algebra ℂ A]
    {ρ : Representation ℂ (unitary ℂ) A}
    (hmul : ∀ (g : unitary ℂ) (x y : A), ρ g (x * y) = ρ g x * ρ g y) {z : unitary ℂ}
    {W₁ W₂ : Submodule ℂ A} {ε₁ ε₂ : ℂ} (h₁ : W₁ ≤ centreEigenspace ρ z ε₁)
    (h₂ : W₂ ≤ centreEigenspace ρ z ε₂) :
    W₁ * W₂ ≤ centreEigenspace ρ z (ε₁ * ε₂)

lemma eq_zero_of_invariant_of_mem_centreEigenspace {ρ : Representation ℂ (unitary ℂ) V}
    {z : unitary ℂ} {ε : ℂ} (hε : ε ≠ 1) {x : V} (hx : x ∈ centreEigenspace ρ z ε)
    (hinv : ∀ u : unitary ℂ, ρ u x = x) : x = 0

lemma mem_of_invariant_of_mem_sup_centreEigenspace {ρ : Representation ℂ (unitary ℂ) V}
    {z : unitary ℂ} {ε : ℂ} (hε : ε ≠ 1) {W : Submodule ℂ V}
    (hW : W ≤ centreEigenspace ρ z ε) (S : Submodule ℂ V)
    (hS : ∀ g : unitary ℂ, ∀ y ∈ S, ρ g y ∈ S) {x : V} (hx : x ∈ W ⊔ S)
    (hinv : ∀ g : unitary ℂ, ρ g x = x) : x ∈ S

