    Module.Dual ℂ (ConjModule (T.FermionValue i)) →ₗ[ℂ] T.LocalFieldAlgebra

noncomputable def covDerivConjBoson (j : T.BosonSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) :
    Module.Dual ℂ (ConjModule (T.BosonValue j)) →ₗ[ℂ] T.LocalFieldAlgebra

lemma covDerivFieldStrength_eq_of_perm_of_map_lie {φ : Module.Dual ℝ G.lieSubalgebra}
    (hφ : ∀ x y : G.lieSubalgebra, φ ⁅x, y⁆ = 0) {l l' : List (Fin 1 ⊕ Fin 3)}
    (hl : l.Perm l') (μ ν : Fin 1 ⊕ Fin 3) :
    T.covDerivFieldStrength l μ ν φ = T.covDerivFieldStrength l' μ ν φ

lemma eq_of_jetDeriv_eq_mul {Y Z : SpaceTimeAlgebra ⊗[ℂ] A}
    (hY : ∀ μ, jetDeriv μ Y = Ω μ * Y) (hZ : ∀ μ, jetDeriv μ Z = Ω μ * Z)
    (h0 : jetEval Y = jetEval Z) : Y = Z

noncomputable def LocalCovFieldAlgebra :
    @Subalgebra ℂ T.LocalFieldAlgebra _ T.ringLocalFieldAlgebra.toSemiring
      T.algebraLocalFieldAlgebra

noncomputable def covConjFermion (i : T.FermionSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) :
    Module.Dual ℂ (ConjModule (T.FermionValue i)) →ₗ[ℂ] T.LocalCovFieldAlgebra

lemma repJet_covBoson (U : G.gaugeJetGroup) (j : T.BosonSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) (φ : Module.Dual ℂ (T.BosonValue j)) :
    repJet T U (covBoson T j l φ) = covBoson T j l (repDualCoeff (T.boson j).repJet U⁻¹ 0 φ)

lemma covConjBoson_mem_kindGenerators (j : T.BosonSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) (φ : Module.Dual ℂ (ConjModule (T.BosonValue j))) :
    covConjBoson T j l φ ∈ T.kindGenerators .scalar

lemma covFermion_mem_kindGenerators (i : T.FermionSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) (φ : Module.Dual ℂ (T.FermionValue i)) :
    covFermion T i l φ ∈ T.kindGenerators .fermion

lemma covConjFermion_mem_kindGenerators (i : T.FermionSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) (φ : Module.Dual ℂ (ConjModule (T.FermionValue i))) :
    covConjFermion T i l φ ∈ T.kindGenerators .fermion

lemma covBoson_mem_weightedGenerators (j : T.BosonSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) (φ : Module.Dual ℂ (T.BosonValue j)) :
    covBoson T j l φ ∈ T.weightedGenerators .scalar ((T.boson j).massWeight + 2 * n)

lemma covConjBoson_mem_weightedGenerators (j : T.BosonSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) (φ : Module.Dual ℂ (ConjModule (T.BosonValue j))) :
    covConjBoson T j l φ ∈ T.weightedGenerators .scalar ((T.boson j).massWeight + 2 * n)

lemma covFermion_mem_weightedGenerators (i : T.FermionSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) (φ : Module.Dual ℂ (T.FermionValue i)) :
    covFermion T i l φ ∈ T.weightedGenerators .fermion ((T.fermion i).massWeight + 2 * n)

lemma covConjFermion_mem_weightedGenerators (i : T.FermionSpecies) {n : ℕ}
    (l : Fin n → (Fin 1 ⊕ Fin 3)) (φ : Module.Dual ℂ (ConjModule (T.FermionValue i))) :
    covConjFermion T i l φ ∈ T.weightedGenerators .fermion ((T.fermion i).massWeight + 2 * n)

lemma le_of_mem_weightedGenerators_fermion {m w : ℕ} {b : T.LocalCovFieldAlgebra}
    (hm : ∀ i, m ≤ (T.fermion i).massWeight) (hb : b ∈ T.weightedGenerators .fermion w) :
    m ≤ w

lemma repJet_mem_weightedGenerators (U : G.gaugeJetGroup) {k : FieldKind} {w : ℕ}
    {b : T.LocalCovFieldAlgebra} (hb : b ∈ T.weightedGenerators k w) :
    LocalCovFieldAlgebra.repJet T U b ∈ T.weightedGenerators k w

lemma mul_mem_weightedMonomials {A B : Finset FieldKind} {v w : ℕ}
    {x y : T.LocalCovFieldAlgebra} (hx : x ∈ T.weightedMonomials A v)
    (hy : y ∈ T.weightedMonomials B w) : x * y ∈ T.weightedMonomials (A ∪ B) (v + w)

lemma repJet_mem_span_weightedMonomials (U : G.gaugeJetGroup) {A : Finset FieldKind} {w : ℕ}
    {x : T.LocalCovFieldAlgebra} (hx : x ∈ Submodule.span ℂ (T.weightedMonomials A w)) :
    LocalCovFieldAlgebra.repJet T U x ∈ Submodule.span ℂ (T.weightedMonomials A w)

lemma repValue_mem_span_weightedMonomials (g : G.group) {A : Finset FieldKind} {w : ℕ}
    {x : T.LocalCovFieldAlgebra} (hx : x ∈ Submodule.span ℂ (T.weightedMonomials A w)) :
    LocalCovFieldAlgebra.repValue T g x ∈ Submodule.span ℂ (T.weightedMonomials A w)

lemma anticomm_of_mem_kindGenerators_fermion {a b : T.LocalCovFieldAlgebra}
    (ha : a ∈ T.kindGenerators .fermion) (hb : b ∈ T.kindGenerators .fermion) :
    a * b = -(b * a)

lemma anticomm_of_mem_span_kindGenerators_fermion {x y : T.LocalCovFieldAlgebra}
    (hx : x ∈ Submodule.span ℂ (T.kindGenerators .fermion))
    (hy : y ∈ Submodule.span ℂ (T.kindGenerators .fermion)) : x * y = -(y * x)

lemma even_of_mem_weightedGenerators (hpar : T.HasMassWeightParity) {k : FieldKind}
    (hk : k ≠ .fermion) {w : ℕ} {b : T.LocalCovFieldAlgebra}
    (hb : b ∈ T.weightedGenerators k w) : Even w

lemma mul_eq_smul_mul_of_mem_span_weightedMonomials (hpar : T.HasMassWeightParity) {v w : ℕ}
    {x y : T.LocalCovFieldAlgebra}
    (hx : x ∈ Submodule.span ℂ (⋃ A, T.weightedMonomials A v))
    (hy : y ∈ Submodule.span ℂ (⋃ A, T.weightedMonomials A w)) :
    x * y = ((-1 : ℂ) ^ (v * w)) • (y * x)

lemma mul_mem_massWeightSubmodule {v w : ℕ} {x y : T.LocalCovFieldAlgebra}
    (hx : x ∈ massWeightSubmodule P v) (hy : y ∈ massWeightSubmodule P w) :
    x * y ∈ massWeightSubmodule P (v + w)

lemma mem_massWeightSubmodule_of_mem_weightedGenerators (hP : IsMassWeightPoly P) {k : FieldKind}
    {w : ℕ} {b : T.LocalCovFieldAlgebra} (hb : b ∈ T.weightedGenerators k w) :
    b ∈ massWeightSubmodule P w

lemma mem_massWeightSubmodule_of_mem_weightedMonomials (hP : IsMassWeightPoly P)
    {A : Finset FieldKind} {w : ℕ} {x : T.LocalCovFieldAlgebra}
    (hx : x ∈ T.weightedMonomials A w) : x ∈ massWeightSubmodule P w

lemma massWeightComponent_of_mem {w : ℕ} {x : T.LocalCovFieldAlgebra}
    (hx : x ∈ massWeightSubmodule P w) (k : ℕ) :
    massWeightComponent P k x = if w = k then x else 0

lemma repJet_mem_massWeightSubmodule (hP : IsMassWeightPoly P) (U : G.gaugeJetGroup) {w : ℕ}
    {x : T.LocalCovFieldAlgebra} (hx : x ∈ massWeightSubmodule P w) :
    repJet T U x ∈ massWeightSubmodule P w

lemma repValue_mem_massWeightSubmodule (hP : IsMassWeightPoly P) (g : G.group) {w : ℕ}
    {x : T.LocalCovFieldAlgebra} (hx : x ∈ massWeightSubmodule P w) :
    repValue T g x ∈ massWeightSubmodule P w

lemma repLorentzGroup_mem_massWeightSubmodule (hP : IsMassWeightPoly P)
    (hGL : T.GaugeLorentzCompatible) (Λ : SL(2,ℂ)) {w : ℕ} {x : T.LocalCovFieldAlgebra}
    (hx : x ∈ massWeightSubmodule P w) : repLorentzGroup T hGL Λ x ∈ massWeightSubmodule P w

lemma massWeightComponent_mem_massWeightSubmoduleLE (hP : IsMassWeightPoly P) {k w : ℕ}
    (hk : k ≤ w) (x : T.LocalCovFieldAlgebra) :
    massWeightComponent P k x ∈ massWeightSubmoduleLE P w

lemma sum_massWeightComponent_of_mem_massWeightSubmoduleLE {w : ℕ} {x : T.LocalCovFieldAlgebra}
    (hx : x ∈ massWeightSubmoduleLE P w) :
    ∑ k ∈ Finset.range (w + 1), massWeightComponent P k x = x

lemma map_mem_massWeightSubmoduleLE {f : T.LocalCovFieldAlgebra →ₗ[ℂ] T.LocalCovFieldAlgebra}
    (hf : ∀ k y, y ∈ massWeightSubmodule P k → f y ∈ massWeightSubmodule P k) {w : ℕ}
    {x : T.LocalCovFieldAlgebra} (hx : x ∈ massWeightSubmoduleLE P w) :
    f x ∈ massWeightSubmoduleLE P w

lemma repValue_mem_massWeightSubmoduleLE (hP : IsMassWeightPoly P) (g : G.group) {w : ℕ}
    {x : T.LocalCovFieldAlgebra} (hx : x ∈ massWeightSubmoduleLE P w) :
    repValue T g x ∈ massWeightSubmoduleLE P w

lemma repLorentzGroup_mem_massWeightSubmoduleLE (hP : IsMassWeightPoly P)
    (hGL : T.GaugeLorentzCompatible) (Λ : SL(2,ℂ)) {w : ℕ} {x : T.LocalCovFieldAlgebra}
    (hx : x ∈ massWeightSubmoduleLE P w) : repLorentzGroup T hGL Λ x ∈ massWeightSubmoduleLE P w

lemma mul_mem_sectorMonomials {A B : Finset FieldKind} {x y : T.LocalCovFieldAlgebra}
    (hx : x ∈ T.sectorMonomials A) (hy : y ∈ T.sectorMonomials B) :
    x * y ∈ T.sectorMonomials (A ∪ B)

lemma repJet_mem_sector (U : G.gaugeJetGroup) {A : Finset FieldKind}
    {x : T.LocalCovFieldAlgebra} (hx : x ∈ T.sector A) :
    LocalCovFieldAlgebra.repJet T U x ∈ T.sector A

lemma mul_mem_sectorMassWeight {A B : Finset FieldKind} {v w : ℕ} {x y : T.LocalCovFieldAlgebra}
    (hx : x ∈ T.sectorMassWeight A v) (hy : y ∈ T.sectorMassWeight B w) :
    x * y ∈ T.sectorMassWeight (A ∪ B) (v + w)

lemma repValue_mem_sectorMassWeight (g : G.group) {A : Finset FieldKind} {w : ℕ}
    {x : T.LocalCovFieldAlgebra} (hx : x ∈ T.sectorMassWeight A w) :
    repValue T g x ∈ T.sectorMassWeight A w

lemma sectorMassWeight_eq_bot_of_lt {A : Finset FieldKind} {w : ℕ} {m : FieldKind → ℕ}
    (hm : ∀ k ∈ A, ∀ v (b : T.LocalCovFieldAlgebra), b ∈ T.weightedGenerators k v → m k ≤ v)
    (hw : w < ∑ k ∈ A, m k) : T.sectorMassWeight A w = ⊥

lemma kindWeight_cons_of_eq {c : FieldKind} {q : FieldKind × ℕ × T.LocalCovFieldAlgebra}
    (hq : q.1 = c) (L : List (FieldKind × ℕ × T.LocalCovFieldAlgebra)) :
    kindWeight c (q :: L) = q.2.1 + kindWeight c L

lemma kindWeight_cons_of_ne {c : FieldKind} {q : FieldKind × ℕ × T.LocalCovFieldAlgebra}
    (hq : q.1 ≠ c) (L : List (FieldKind × ℕ × T.LocalCovFieldAlgebra)) :
    kindWeight c (q :: L) = kindWeight c L

lemma kindWeight_ne_zero (hpos : T.HasPositiveMassWeights) {c : FieldKind}
    {L : List (FieldKind × ℕ × T.LocalCovFieldAlgebra)}
    (hL : ∀ p ∈ L, p.2.2 ∈ T.weightedGenerators p.1 p.2.1)
    (hc : c ∈ (L.map Prod.fst).toFinset) : kindWeight c L ≠ 0

